+
+const T0 = "2026-08-10T00:00:00.000Z";
+const T1 = "2026-08-10T00:01:00.000Z";
+const T2 = "2026-08-10T00:02:00.000Z";
+const PROVIDER: ProviderSettings = {
+  provider: "openai",
+  model: "gpt-5",
