+    id: `branch.${sessionId}`,
+    sessionId,
+    createdAt,
+    updatedAt,
+  };
+}
+
+function session(id: string, messages: LearnerSession["messages"], options: Partial<LearnerSession> = {}): LearnerSession {
+  return {
+    id,
+    title: id,
